CREATE OR REPLACE VIEW public.user_top100_progress_view AS WITH list_totals AS (SELECT tl.id, tl.slug, tl.name, COUNT(DISTINCT ctm.course_id) AS total_courses FROM public.top100_lists tl JOIN public.course_top100_memberships ctm ON ctm.list_id = tl.id WHERE tl.is_active = true GROUP BY tl.id, tl.slug, tl.name) SELECT cr.user_id, lt.id AS list_id, lt.slug AS list_slug, lt.name AS list_name, lt.total_courses AS total_courses_in_list, COUNT(DISTINCT cr.course_id) AS courses_rated_in_list, COUNT(DISTINCT cr.course_id) AS courses_played_in_list FROM list_totals lt JOIN public.course_top100_memberships ctm ON ctm.list_id = lt.id JOIN public.course_ratings cr ON cr.course_id = ctm.course_id WHERE cr.rating IS NOT NULL GROUP BY cr.user_id, lt.id, lt.slug, lt.name, lt.total_courses;